import{z as B,x as d,o as r,c as A,q as n,j as i,D as e,d as t,s as o,S as E,b as s}from"./chunks/framework.C8m1ZpeB.js";const U=JSON.parse('{"title":"移位与桶形移位","description":"","frontmatter":{"title":"移位与桶形移位","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/barrel-shifter.md","filePath":"cs/barrel-shifter.md","lastUpdated":1791063341000}'),p={name:"cs/barrel-shifter.md"};function c(D,a,h,m,f,C){const l=d("Mermaid");return r(),A("div",null,[a[2]||(a[2]=n('<h1 id="移位与桶形移位" tabindex="-1">移位与桶形移位 <a class="header-anchor" href="#移位与桶形移位" aria-label="Permalink to &quot;移位与桶形移位&quot;">​</a></h1><div class="epigraph"><p>移 $k$ 位可以串 $k$ 个一位移位器，也可以用对数级 MUX 一次选出；后者叫桶形，延迟按选择层数算。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/array-multiplier">阵列乘法</a>用「左移再加」描述部分积，但移位本身还不是一块有名字的组合电路。本课不重铺部分积，也不从 RV32I 的 <code>sll</code> 编码另起。缺口是：<strong>任意移位量</strong>如何在一级组合里完成，供后课 ALU 接线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逻辑左移、逻辑右移、算术右移（复制符号）语义已在<a href="/cs/twos-complement">补码</a>与乘法课出现。缺口是实现：一位移位器是接线加 MUX；要移 \\(0..n-1\\)，串行 \\(n\\) 级则延迟 \\(\\Theta(n)\\)。桶形移位器：第 \\(i\\) 层按移位量的第 \\(i\\) 位选择「移 \\(2^i\\) 或 0」，深度 \\(\\Theta(\\log n)\\)，面积 \\(\\Theta(n\\log n)\\) 个 MUX。</p><p>循环移位、漏斗移位点到为止。本课钉桶形作为 ALU 家族的第三块（加、逻辑、移）。</p><h3 id="桶形不是「异步提前执行移位指令」" tabindex="-1">桶形不是「异步提前执行移位指令」 <a class="header-anchor" href="#桶形不是「异步提前执行移位指令」" aria-label="Permalink to &quot;桶形不是「异步提前执行移位指令」&quot;">​</a></h3><p>名字里的 barrel 指交叉开关/多层 MUX，仍是同一组合云。与<a href="/cs/adder-cla">CLA</a>一样，不要理解成流水线超前。移位量来自指令立即数或寄存器低位，本课不译码 opcode。</p><p><span class="marginnote">Harris 画 log 级 MUX 树。Patterson/Hennessy 的 ALU 含移位。<code>srl</code>/<code>sra</code> 差在空位填 0 还是填符号，只改最高位那一路的数据源。</span></p><p><span class="marginnote">直觉类比：串行移位像爬楼梯一层层挪，移 13 位就要停 13 站；桶形像一部每层都可设「直达」的电梯，把 13 拆成 8+4+1 三段跳完。深度从线性降到对数，代价是每层都得装 MUX 开关，面积变大。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据 \\(n\\) 位、量 \\(k=\\lceil\\log_2 n\\rceil\\) 位。层 \\(i\\)：MUX 选原值或右（左）移 \\(2^i\\) 后的值，空位按逻辑/算术规则填。三态/传输门也可搭交叉阵，延迟模型仍按<a href="/cs/critical-path">关键路径</a>。</p>',12)),(r(),i(E,null,{default:e(()=>[o(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%95%B0%E6%8D%AE%E4%B8%8E%E7%A7%BB%E4%BD%8D%E9%87%8F%22%5D%20--%3E%20L0%5B%22MUX%20%E5%B1%82%EF%BC%9A%E7%A7%BB%201%20%E6%88%96%200%22%5D%0A%20%20L0%20--%3E%20L1%5B%22MUX%20%E5%B1%82%EF%BC%9A%E7%A7%BB%202%20%E6%88%96%200%22%5D%0A%20%20L1%20--%3E%20LN%5B%22%E7%9B%B4%E8%87%B3%202%5E%7Bk-1%7D%22%5D%0A%20%20LN%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AALU%20%E7%BB%93%E6%9E%9C%20MUX%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[t("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"后课 ALU 把移位器输出送进结果 MUX，与加减、逻辑并列。关键路径可能被桶形或 CLA 主导，设计时要比，不能默认「移位免费」。多周期可用一位移位器加计数器，面积小、CPI 随 \\(k\\) 涨——与乘法的两种实现同一权衡。",-1)),(r(),i(E,null,{default:e(()=>[o(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E7%A7%BB%E4%BD%8D%E9%87%8F%2013%20%3D%20%E4%BA%8C%E8%BF%9B%E5%88%B6%201101%22%5D%20--%3E%20CHK%7B%22%E6%AF%8F%E5%B1%82%E5%8F%AA%E7%9C%8B%E8%87%AA%E5%B7%B1%E9%82%A3%E4%B8%80%E4%BD%8D%22%7D%0A%20%20CHK%20--%3E%7C%22%E4%BD%8D%200%20%3D%201%22%7C%20LY0%5B%22%E5%B1%82%200%3A%20%E7%A7%BB%201%20%E4%BD%8D%22%5D%0A%20%20CHK%20--%3E%7C%22%E4%BD%8D%201%20%3D%200%22%7C%20LY1%5B%22%E5%B1%82%201%3A%20%E7%9B%B4%E9%80%9A%22%5D%0A%20%20CHK%20--%3E%7C%22%E4%BD%8D%202%20%3D%201%22%7C%20LY2%5B%22%E5%B1%82%202%3A%20%E7%A7%BB%204%20%E4%BD%8D%22%5D%0A%20%20CHK%20--%3E%7C%22%E4%BD%8D%203%20%3D%201%22%7C%20LY3%5B%22%E5%B1%82%203%3A%20%E7%A7%BB%208%20%E4%BD%8D%22%5D%0A%20%20LY0%20--%3E%20SUM%5B%22%E4%B8%B2%E8%81%94%E5%90%8E%E5%90%88%E8%AE%A1%E7%A7%BB%2013%20%E4%BD%8D%22%5D%0A%20%20LY1%20--%3E%20SUM%0A%20%20LY2%20--%3E%20SUM%0A%20%20LY3%20--%3E%20SUM%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">数字实例：8 位数据移 13 位，\\(13 = 8 + 4 + 1\\)（二进制 1101）。桶形只让层 0、2、3 的 MUX 打到「移位」档，层 1 直通，串联起来正好移 \\(1+4+8=13\\)。任意移位量都能拆成 2 的幂之和——这就是对数深度的来历。</span></p><p><span class="marginnote">常见误区：初学者容易把逻辑右移与算术右移当成两块电路。它们共享同一套 MUX 层，只差最高位空出的填法：<code>srl</code> 填 0，<code>sra</code> 复制符号位；硬件上只是最高那一路多一个数据源选择，不另建一层。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 SIMD 跨通道 shuffle、不把浮点对阶移位当同一块规范。旋转与漏斗是桶形的接线变体，不单开课。</p><p>后课默认：任意移位量可用 \\(\\log n\\) 级 MUX 组合完成；ALU 含这一口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一位串移延迟线性；桶形用对数级 MUX。</li><li>逻辑/算术右移只差空位填充。</li><li>仍是组合，计入 ALU 关键路径。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',7))])}const _=B(p,[["render",c]]);export{U as __pageData,_ as default};
